 $html = '<section id="odpc-tv" style="max-width:1200px;margin:auto;background:#101c30;color:#fff;padding:20px;border-radius:16px"><h2 style="color:#fff">ODPC TV</h2><p>Sender direkt hier ansehen. Die Quellen stammen aus der öffentlichen IPTV-Senderliste; einzelne Streams können ausfallen oder regional gesperrt sein.</p><video id="odpc-tv-video" controls playsinline style="width:100%;aspect-ratio:16/9;background:#000;border-radius:12px"></video><p id="odpc-tv-status" role="status">Sender auswählen</p><input id="odpc-tv-search" type="search" aria-label="Sender suchen" placeholder="Sender suchen…" style="width:100%;padding:12px;margin:8px 0;border-radius:8px"><label style="display:block;margin:10px 0"><input id="odpc-tv-favs-only" type="checkbox"> Nur Favoriten</label><div id="odpc-tv-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:8px"></div></section>';
 $html .= '<script src="https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js"></script>';
 $html .= '<script>(function(){const root=document.getElementById("odpc-tv");if(!root)return;const channels=JSON.parse(root.dataset.channels||"[]"),v=root.querySelector("video"),status=root.querySelector("#odpc-tv-status"),grid=root.querySelector("#odpc-tv-grid"),search=root.querySelector("#odpc-tv-search"),only=root.querySelector("#odpc-tv-favs-only");let h=null;let fav=[];try{fav=JSON.parse(localStorage.getItem("odpc-tv-favorites-v1")||"[]")}catch(e){}function play(c){if(h){h.destroy();h=null}v.pause();v.removeAttribute("src");v.load();status.textContent="Verbinde: "+c.name;if(window.Hls&&Hls.isSupported()){h=new Hls({enableWorker:true});h.loadSource(c.url);h.attachMedia(v);h.on(Hls.Events.MANIFEST_PARSED,()=>v.play().catch(()=>status.textContent="Zum Starten Play drücken"));h.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal){status.textContent="Dieser Stream ist derzeit nicht abspielbar ("+e.type+"). Bitte anderen Sender wählen.";h.destroy();h=null}})}else if(v.canPlayType("application/vnd.apple.mpegurl")){v.src=c.url;v.play().catch(()=>status.textContent="Zum Starten Play drücken")}else status.textContent="HLS wird in diesem Browser nicht unterstützt"}function render(){grid.replaceChildren();const q=search.value.trim().toLowerCase();for(const c of channels){if(!c.name.toLowerCase().includes(q)||(only.checked&&!fav.includes(c.name)))continue;const wrap=document.createElement("div");wrap.style.cssText="display:flex;gap:3px";const b=document.createElement("button");b.type="button";b.textContent=c.name;b.style.cssText="flex:1;min-width:0;overflow-wrap:anywhere;background:#254d80;color:#fff;border:0;border-radius:8px;padding:12px;cursor:pointer";b.onclick=()=>play(c);const star=document.createElement("button");star.type="button";star.textContent=fav.includes(c.name)?"★":"☆";star.setAttribute("aria-label","Favorit "+c.name);star.style.cssText="background:#36536f;color:white;border:0;border-radius:8px;padding:10px;cursor:pointer";star.onclick=()=>{fav=fav.includes(c.name)?fav.filter(x=>x!==c.name):[...fav,c.name];try{localStorage.setItem("odpc-tv-favorites-v1",JSON.stringify(fav))}catch(e){}render()};wrap.append(b,star);grid.appendChild(wrap)}}search.addEventListener("input",render);only.addEventListener("change",render);render()})();</script>';
